import React, { useState } from "react";
import axios from "axios";
import "./App.css";

const operations = {
  gray: { label: "Gri Dönüşüm", url: "/process/gray" },
  binary: { label: "Binary Dönüşüm", url: "/process/binary", params: ["threshold"] },
  rotate: { label: "Görüntü Döndürme", url: "/process/rotate", params: ["angle"] },
  crop: { label: "Görüntü Kırpma", url: "/process/crop", params: ["x", "y", "width", "height"] },
  zoom: { label: "Görüntü Yaklaştırma/Uzaklaştırma", url: "/process/zoom", params: ["scale"] },
  color: { label: "Renk Uzayı Dönüşümleri", url: "/process/color", params: ["mode"] },
  histogram: { label: "Histogram Germe/Genişletme", url: "/process/histogram" },
  arithmetic: { label: "Aritmetik İşlemler (Çıkarma, Çarpma)", url: "/process/arithmetic", params: ["arithmetic_op"] },
  contrast: { label: "Kontrast Azaltma", url: "/process/contrast", params: ["factor"] },
  median: { label: "Konvolüyon (Median)", url: "/process/median", params: ["kernel_size"] },
  double_threshold: { label: "Çift Eşikleme", url: "/process/double_threshold", params: ["low_thresh", "high_thresh"] },
  edge: { label: "Kenar Algılama (Canny)", url: "/process/edge", params: ["threshold1", "threshold2"] },
  noise: { label: "Gürültü Ekleme", url: "/process/noise", params: ["salt_amount", "pepper_amount"] },
  denoise: { label: "Gürültü Temizleme", url: "/process/denoise", params: ["filter_type", "kernel_size"] },
  motion: { label: "Motion Filtresi", url: "/process/motion", params: ["kernel_size"] },
  morphology: { label: "Morfolojik İşlemler", url: "/process/morphology", params: ["morph_op", "kernel_size"] },
};

const defaultParamsByOperation = {
  binary: { threshold: 127 }, // orta seviye eşikleme
  double_threshold: { low_thresh: 50, high_thresh: 120 }, // kenar tespiti için yaygın değerler
  edge: { threshold1: 50, threshold2: 100 }, // Canny kenar algılama için iyi başlangıç
  crop: { x: 50, y: 50, width: 200, height: 200 }, // orta büyüklükte bir alan kesme
  zoom: { scale: 1.5 }, // görüntüyü %50 oranında büyütme
  rotate: { angle: 90 }, // 90 derece döndürme
  contrast: { factor: 0.8 }, // kontrastı hafif azaltma
  median: { kernel_size: 5 }, // tipik blur etkisi için uygun
  denoise: { filter_type: "median", kernel_size: 3 }, // gürültü temizlemede median yaygındır
  motion: { kernel_size: 20 }, // motion için daha belirgin efekt
  noise: { salt_amount: 0.03, pepper_amount: 0.03 }, // orta seviye gürültü
  morphology: { morph_op: "open", kernel_size: 5 }, // açma işlemi yaygın ve etkilidir
  arithmetic: { arithmetic_op: "multiply" }, // etkisi belirgin birleştirme
  color: { mode: "hsv" } // en yaygın renk uzayı dönüşümü
};


function App() {
  const [selectedOperation, setSelectedOperation] = useState("gray");
  const [file, setFile] = useState(null);
  const [secondFile, setSecondFile] = useState(null);
  const [params, setParams] = useState(defaultParamsByOperation[selectedOperation] || {});
  const [resultUrl, setResultUrl] = useState(null);

  const handleParamChange = (e) => {
    setParams({ ...params, [e.target.name]: e.target.value });
  };

  const handleSubmit = async () => {
    const operation = operations[selectedOperation];
    const formData = new FormData();
    formData.append("file", file);
    if (selectedOperation === "arithmetic") {
      formData.append("file2", secondFile);
    }
    if (operation.params) {
      operation.params.forEach((param) => {
        formData.append(param, params[param] || "");
      });
    }
    try {
      const response = await axios.post(`http://localhost:8001${operation.url}`, formData, {
        responseType: "blob",
      });
      setResultUrl(URL.createObjectURL(response.data));
    } catch (err) {
      console.error("İşlem sırasında hata oluştu:", err);
    }
  };

  const renderParamInputs = () => {
    const op = operations[selectedOperation];
    if (!op.params) return null;
    return (
      <div className="params">
        {op.params.map((param) => (
          param === "mode" ? (
            <div className="param-field" key={param}>
              <label htmlFor="mode">Renk Uzayı:</label>
              <select name="mode" value={params.mode || defaultParamsByOperation.color.mode} onChange={handleParamChange}>
                <option value="hsv">HSV</option>
                <option value="ycbcr">YCbCr</option>
                <option value="lab">Lab</option>
              </select>
            </div>
          ) : param === "arithmetic_op" ? (
            <div className="param-field" key={param}>
              <label htmlFor="arithmetic_op">İşlem Tipi:</label>
              <select name="arithmetic_op" value={params.arithmetic_op || defaultParamsByOperation.arithmetic.arithmetic_op} onChange={handleParamChange}>
                <option value="subtract">Çıkarma</option>
                <option value="multiply">Çarpma</option>
              </select>
            </div>
          ) : param === "filter_type" ? (
            <div className="param-field" key={param}>
              <label htmlFor="filter_type">Filtre Türü:</label>
              <select name="filter_type" value={params.filter_type || defaultParamsByOperation.denoise.filter_type} onChange={handleParamChange}>
                <option value="mean">Mean</option>
                <option value="median">Median</option>
              </select>
            </div>
          ) : param === "morph_op" ? (
            <div className="param-field" key={param}>
              <label htmlFor="morph_op">Morfolojik İşlem:</label>
              <select name="morph_op" value={params.morph_op || defaultParamsByOperation.morphology.morph_op} onChange={handleParamChange}>
                <option value="dilate">Genişletme</option>
                <option value="erode">Aşındırma</option>
                <option value="open">Açma</option>
                <option value="close">Kapama</option>
              </select>
            </div>
          ) : param === "salt_amount" || param === "pepper_amount" ? (
            <div className="param-field" key={param}>
              <label htmlFor={param}>{param.replace("_", " ").toUpperCase()}</label>
              <input
                id={param}
                name={param}
                type="number"
                min="0"
                max="1"
                step="0.01"
                value={params[param] || defaultParamsByOperation.noise[param]}
                onChange={handleParamChange}
              />
            </div>
          ) : (
            <div className="param-field" key={param}>
              <label htmlFor={param}>{param.replace("_", " ").toUpperCase()}</label>
              <input
                id={param}
                name={param}
                type="text"
                value={params[param] || ""}
                onChange={handleParamChange}
              />
            </div>
          )
        ))}
      </div>
    );
  };

  return (
    <div className="app-container">
      <h1>Görüntü İşleme Arayüzü</h1>
      <div className="controls">
        <input type="file" onChange={(e) => setFile(e.target.files[0])} />
        {selectedOperation === "arithmetic" && (
          <input type="file" onChange={(e) => setSecondFile(e.target.files[0])} />
        )}
        <select value={selectedOperation} onChange={(e) => {
          setSelectedOperation(e.target.value);
          setParams(defaultParamsByOperation[e.target.value] || {});
        }}>
          {Object.keys(operations).map((op) => (
            <option key={op} value={op}>{operations[op].label}</option>
          ))}
        </select>
        {renderParamInputs()}
        <button onClick={handleSubmit}>Uygula</button>
      </div>
      <div className="image-display">
        {file && <img src={URL.createObjectURL(file)} alt="Orijinal" />}
        {selectedOperation === "arithmetic" && secondFile && (
          <img src={URL.createObjectURL(secondFile)} alt="İkinci Görsel" />
        )}
        {resultUrl && <img src={resultUrl} alt="Sonuç" />}
      </div>
    </div>
  );
}

export default App;
